mapper.sql:
SELECT sl.id as sampleLedgerId, sl.user_id AS userId, sl.user_name AS userName, sl.dept_id AS deptId, sl.dept_name AS deptName, sl.use_user_id AS useUserId, sl.use_user_name AS useUserName, sl.sku_id AS skuId, sl.sku_no AS skuNo, sl.product_name AS productName, COALESCE(sl.qty, 0) as ledgerQty ,
COALESCE(sl.qty, 0) - COALESCE(aa.freezeQty, 0) AS availableQty
COALESCE(sl.qty, 0) AS availableQty
FROM sample_ledger sl
left join ( select ssd.sample_ledger_id , sum(ssd.scrap_qty) as freezeQty from sample_scrap_info ssi inner join sample_scrap_detail ssd on ssi.id = ssd.main_id and ssd.is_deleted = false where ssi.is_deleted = false and ssi.invalid_status = false and ssi.approve_status !='approve'
and ssi.id != #{params.childId}
GROUP BY ssd.sample_ledger_id) as aa on aa.sample_ledger_id = sl.id
left join ( select ssd.sample_ledger_id , sum(ssd.borrow_qty) as freezeQty from sample_borrow_info ssi inner join sample_borrow_detail ssd on ssi.id = ssd.main_id and ssd.is_deleted = false where ssi.is_deleted = false and ssi.invalid_status = false and ssi.approve_status !='approve'
and ssi.id != #{params.childId}
GROUP BY ssd.sample_ledger_id) as aa on aa.sample_ledger_id = sl.id
left join ( select ssd.sample_ledger_id , sum(ssd.qty) as freezeQty from sample_back_info ssi inner join sample_back_detail ssd on ssi.id = ssd.main_id and ssd.is_deleted = false where ssi.is_deleted = false and ssi.invalid_status = false and ssi.approve_status !='approve'
and ssi.id != #{params.childId}
GROUP BY ssd.sample_ledger_id ) as aa on aa.sample_ledger_id = sl.id
left join ( select ssd.sample_ledger_id , sum(ssd.transfer_qty) as freezeQty from sample_transfer_info ssi inner join sample_transfer_detail ssd on ssi.id = ssd.main_id and ssd.is_deleted = false where ssi.is_deleted = false and ssi.invalid_status = false and ssi.approve_status !='approve'
and ssi.id != #{params.childId}
GROUP BY ssd.sample_ledger_id ) as aa on aa.sample_ledger_id = sl.id
left join ( select ssd.sample_ledger_id , sum(ssd.difference_qty) as freezeQty from sample_adjustment_info ssi inner join sample_adjustment_detail ssd on ssi.id = ssd.main_id and ssd.is_deleted = false where ssi.is_deleted = false and ssi.invalid_status = false and ssi.approve_status !='approve'
and ssi.id != #{params.childId}
GROUP BY ssd.sample_ledger_id ) as aa on aa.sample_ledger_id = sl.id
WHERE sl.is_deleted = FALSE
AND sl.user_id = #{ params.userId}
and sl.id in
#{item}
and sl.sku_id in
#{item}
and sl.use_user_id = #{params.useUserId}
and sl.use_user_name ILIKE concat('%',#{params.useUserName}::text,'%')
and sl.sku_no in
#{item}
and sl.sku_no ILIKE concat('%',#{params.skuNo}::text,'%')
ORDER BY sl.use_user_name, sl.sku_no

